INSERT INTO productos (nombre, precio, descripcion, id_seccion) VALUES ('GREEN ATTITUDE', 15.99, 'Sumérgete en la naturaleza a través de una salida verde en la que la artemisia se une a una chispeante piña y bergamota para refrescarse con un suave acorde marino. En el corazón, el sándalo y la salvia se funden con unas notas florales muy naturales para destacar el amor por la naturaleza de este perfume. Como despedida, unas notas muy masculinas amaderadas se funden con la untuosidad única de la tonka y el praliné unidas al musc, que alarga la duración del perfume en la piel haciendo de él un aroma único en todos los sentidos.', 1);
