INSERT INTO productos (nombre, precio, descripcion, id_seccion) VALUES ('SPF NIGHT ATTITUDE 100 ML', 15.99, 'Nigth Attitude tiene una personalidad absolutamente atractiva. Las intensas notas de salida de menta y pimienta rosa marcan el carácter de este perfume. En el corazón, la lavanda y la salvia se unen a la canela para envolverse con el intenso y oscuro fondo de madera-ámbar y el toque gourmand de la castaña.El magnífico frasco de las fragancias Attitude se oscurece para llevarnos hasta una noche muy especial. El clásico tapón de la colección se pinta de negro y acompaña a una fragancia en color grisáceo muy seductora. Una botella nocturna, rebelde y absolutamente tentadora que llama la atención desde la primera mirada.', 1);
