INSERT INTO productos (nombre, precio, descripcion, id_seccion) VALUES ('True Attitude', 15.99, 'Déjate seducir por el carácter único de este perfume. En su corazón, joven y masculino, la lavanda y las especias, con una nota de pétalos de rosa, se realzan por el frescor del ruibarbo, las hojas de violeta y el dulzor de la manzana roja. En la nota de fondo, la elegancia de las maderas exóticas con la tonka nos descubre la personalidad magnética de este perfume,los perfumes de la gama son R[eco]nsider, y cuentan con un 96% de ingredientes de origen natural, su fórmula es un 97% biodegradable y 100% vegana. Este espíritu también se traslada a los envases en los que solo utilizamos papel procedente de fuentes respetuosas con la naturaleza.', 1);
