INSERT INTO productos (nombre, precio, descripcion, id_seccion) VALUES ('SPICY WOOD', 10.99, 'Inspira profundamente y descubre la auténtica esencia de la naturaleza. Siente la inspiradora fuerza y personalidad de las maderas especiadas en esta nueva fragancia. Su exclusivo diseño se inspira en los ingredientes que forman su aroma y en la propia naturaleza. Tonos azul neutro con efecto hendido que aportan mucha originalidad al diseño y combinan a la perfección con un frasco cilíndrico que tiene un tapón de madera que conecta directamente con la esencia natural de los ingredientes que conforman esta inolvidable fragancia. Siente el verdadero aroma de la naturaleza en esta nueva edición limitada exclusiva en tiendas Springfield.', 1);
